<script lang="ts">
  // Topology view (WO-08 redesign): a deterministic layered fabric map.
  //
  // The document comes from the Rust projection (mock: committed goldens
  // generated BY that projection). This component renders only the nodes
  // and edges present in that document — it never derives relationships,
  // gateways, or connectivity itself. The map is a pure function of the
  // document: interfaces are placed in dependency layers (a member/child
  // sits to the right of the master/parent it attaches to), gateways sit in
  // the final layer, and rows are ordered by ifindex/address. No force
  // simulation, no random placement.
  //
  // WO-02 test/inspection hook preserved: read-only counts plus a
  // deterministic selection that invokes exactly the same callback as a
  // click. Exposed ONLY in development or with the explicit
  // ?araiguma-test-hooks parameter, and removed when the view unmounts.

  import type {
    NetworkSnapshot,
    NodeId,
    TopologyDocument,
    TopologyEdge,
    TopologyNode,
  } from '../types';
  import { kindLabel } from '../lib/format';
  import {
    availabilityEvidenceLabel,
    connectionsAvailability,
    dnsAvailability,
    formatCount,
  } from '../lib/observability';
  import { navigateTo } from '../lib/navigation.svelte';
  import { formatObservationTime } from '../lib/import';
  import { edgeKindLabel, evidenceLabel, nodeIdKey } from '../lib/topology';
  import DataBadge from './DataBadge.svelte';

  let {
    document,
    snapshot = null,
    highlight = [],
    onselect,
  }: {
    document: TopologyDocument;
    /** The current snapshot, used only for the service-observation strip.
     *  It is never used to invent topology nodes or edges. */
    snapshot?: NetworkSnapshot | null;
    highlight?: NodeId[];
    onselect?: (node: TopologyNode) => void;
  } = $props();

  // ── Deterministic layout ────────────────────────────────────────────────
  const NODE_W = 168;
  const NODE_H = 58;
  const COL_GAP = 104;
  const ROW_GAP = 82;
  const PAD_X = 36;
  const PAD_Y = 30;

  interface LaidOutNode {
    node: TopologyNode;
    key: string;
    layer: number;
    x: number;
    y: number;
  }

  interface LaidOutEdge {
    edge: TopologyEdge;
    index: number;
    from: LaidOutNode;
    to: LaidOutNode;
    path: string;
    observed: boolean;
    structural: boolean;
  }

  interface EdgeRow {
    key: string;
    index: number;
    edge: TopologyEdge;
    from: TopologyNode;
    to: TopologyNode;
    kind: string;
    evidence: string;
    observed: boolean;
  }

  const layout = $derived.by(() => {
    const keyOf = nodeIdKey;
    const byKey = new Map(document.nodes.map((node) => [keyOf(node.id), node]));

    // Interface-to-interface relations (bridge/bond membership, parent
    // links, veth peers) define the attachment layers. A relation points
    // from the attached node to the node it attaches to, so the target is
    // closer to the host and the source is placed one layer further out.
    // The bounded relaxation is deterministic and cycle-safe.
    const interfaceLayer = new Map<string, number>();
    for (const node of document.nodes) {
      if ('interface' in node.id) interfaceLayer.set(keyOf(node.id), 0);
    }
    const structuralEdges = document.edges.filter(
      (edge) => 'interface' in edge.from && 'interface' in edge.to,
    );
    for (let pass = 0; pass <= document.nodes.length; pass += 1) {
      let changed = false;
      for (const edge of structuralEdges) {
        const fromKey = keyOf(edge.from);
        const toKey = keyOf(edge.to);
        const wanted = (interfaceLayer.get(toKey) ?? 0) + 1;
        if ((interfaceLayer.get(fromKey) ?? 0) < wanted) {
          interfaceLayer.set(fromKey, wanted);
          changed = true;
        }
      }
      if (!changed) break;
    }

    const maxInterfaceLayer = Math.max(0, ...interfaceLayer.values());
    const gatewayLayer = maxInterfaceLayer + 1;
    const layerOf = (node: TopologyNode): number =>
      'gateway' in node.id
        ? gatewayLayer
        : (interfaceLayer.get(keyOf(node.id)) ?? 0);
    const maxLayer = gatewayLayer;

    const groups = new Map<number, TopologyNode[]>();
    for (const node of document.nodes) {
      const layer = layerOf(node);
      const group = groups.get(layer);
      if (group) group.push(node);
      else groups.set(layer, [node]);
    }
    for (const group of groups.values()) {
      group.sort((a, b) => {
        if ('interface' in a.id && 'interface' in b.id) {
          return a.id.interface.ifindex - b.id.interface.ifindex;
        }
        if ('gateway' in a.id && 'gateway' in b.id) {
          return a.id.gateway.address.localeCompare(b.id.gateway.address);
        }
        return a.label.localeCompare(b.label);
      });
    }

    const maxRows = Math.max(1, ...[...groups.values()].map((group) => group.length));
    const width = PAD_X * 2 + (maxLayer + 1) * NODE_W + maxLayer * COL_GAP;
    const height = PAD_Y * 2 + maxRows * NODE_H + (maxRows - 1) * ROW_GAP;

    const positioned = new Map<string, LaidOutNode>();
    for (const [layer, group] of [...groups.entries()].sort((a, b) => a[0] - b[0])) {
      const offset = ((maxRows - group.length) * (NODE_H + ROW_GAP)) / 2;
      group.forEach((node, index) => {
        const key = keyOf(node.id);
        positioned.set(key, {
          node,
          key,
          layer,
          x: PAD_X + NODE_W / 2 + layer * (NODE_W + COL_GAP),
          y: PAD_Y + offset + index * (NODE_H + ROW_GAP) + NODE_H / 2,
        });
      });
    }

    const nodes = document.nodes
      .map((node) => positioned.get(keyOf(node.id)))
      .filter((entry): entry is LaidOutNode => entry !== undefined);

    const edgePath = (from: LaidOutNode, to: LaidOutNode): string => {
      let sx: number;
      let sy: number;
      let tx: number;
      let ty: number;
      if (Math.abs(to.x - from.x) < 1) {
        sx = from.x;
        tx = to.x;
        sy = to.y > from.y ? from.y + NODE_H / 2 : from.y - NODE_H / 2;
        ty = to.y > from.y ? to.y - NODE_H / 2 : to.y + NODE_H / 2;
        const mid = (sy + ty) / 2;
        return `M ${sx} ${sy} C ${sx} ${mid}, ${tx} ${mid}, ${tx} ${ty}`;
      }
      if (to.x > from.x) {
        sx = from.x + NODE_W / 2;
        tx = to.x - NODE_W / 2;
      } else {
        sx = from.x - NODE_W / 2;
        tx = to.x + NODE_W / 2;
      }
      sy = from.y;
      ty = to.y;
      const dx = tx - sx;
      return `M ${sx} ${sy} C ${sx + dx * 0.42} ${sy}, ${tx - dx * 0.42} ${ty}, ${tx} ${ty}`;
    };

    const edges: LaidOutEdge[] = [];
    document.edges.forEach((edge, index) => {
      const from = positioned.get(keyOf(edge.from));
      const to = positioned.get(keyOf(edge.to));
      if (!from || !to) return;
      edges.push({
        edge,
        index,
        from,
        to,
        path: edgePath(from, to),
        observed: 'observed' in edge.evidence,
        structural: 'interface' in edge.from && 'interface' in edge.to,
      });
    });

    return { width, height, nodes, edges, byKey };
  });

  const edgeRows = $derived.by((): EdgeRow[] => {
    const rows: EdgeRow[] = [];
    document.edges.forEach((edge, index) => {
      const from = layout.byKey.get(nodeIdKey(edge.from));
      const to = layout.byKey.get(nodeIdKey(edge.to));
      if (!from || !to) return;
      rows.push({
        key: `relation-${index}`,
        index,
        edge,
        from,
        to,
        kind: edgeKindLabel(edge.edgeKind),
        evidence: evidenceLabel(edge.evidence),
        observed: 'observed' in edge.evidence,
      });
    });
    return rows;
  });

  const highlightKeys = $derived(new Set(highlight.map((id) => nodeIdKey(id))));

  function select(node: TopologyNode): void {
    onselect?.(node);
  }

  function onNodeKey(event: KeyboardEvent, node: TopologyNode): void {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      select(node);
    }
  }

  function nodeSubtitle(node: TopologyNode): string {
    if (node.nodeKind === 'gateway') return 'gateway · routing fact';
    return node.interfaceKind ? kindLabel(node.interfaceKind) : 'interface';
  }

  function nodeAria(node: TopologyNode): string {
    if (node.nodeKind === 'gateway') {
      return `${node.label}, gateway observed from a routing-table entry. Reachability is not tested.`;
    }
    const kind = node.interfaceKind ? kindLabel(node.interfaceKind) : 'interface';
    return `${node.label}, ${kind}, state ${node.state}`;
  }

  function labelFontSize(label: string): number {
    if (label.length <= 18) return 13;
    if (label.length <= 24) return 11.5;
    return 10;
  }

  function hexPoints(node: LaidOutNode): string {
    const left = node.x - NODE_W / 2;
    const right = node.x + NODE_W / 2;
    const top = node.y - NODE_H / 2;
    const bottom = node.y + NODE_H / 2;
    const cut = 13;
    return `${left + cut},${top} ${right - cut},${top} ${right},${node.y} ${right - cut},${bottom} ${left + cut},${bottom} ${left},${node.y}`;
  }

  // ── Service observations (current snapshot, never the topology) ─────────
  const dns = $derived(snapshot ? dnsAvailability(snapshot) : null);
  const connections = $derived(snapshot ? connectionsAvailability(snapshot) : null);
  const dnsObservations = $derived(snapshot?.dns ?? []);
  const dnsServers = $derived(
    dnsObservations.reduce((total, observation) => total + observation.servers.length, 0),
  );
  const connectionObservations = $derived(snapshot?.connections ?? []);
  const activeConnections = $derived(
    connectionObservations.filter((connection) => connection.state === 'activated').length,
  );
  const differentObservationTimes = $derived(
    snapshot !== null && snapshot.timestampMs !== document.sourceTimestampMs,
  );

  // ── Test/inspection hook (same contract as WO-02) ───────────────────────
  const TEST_HOOK_PARAM = 'araiguma-test-hooks';
  const testHooksEnabled =
    import.meta.env.DEV ||
    (typeof window !== 'undefined' &&
      new URLSearchParams(window.location.search).has(TEST_HOOK_PARAM));

  $effect(() => {
    if (!testHooksEnabled) return;
    const currentDocument = document;
    const selectFromHook = onselect;
    (window as unknown as Record<string, unknown>).__araigumaTopology = {
      nodeCount: currentDocument.nodes.length,
      edgeCount: currentDocument.edges.length,
      nodeLabels: currentDocument.nodes.map((node) => node.label),
      selectNode: (label: string) => {
        const node = currentDocument.nodes.find((candidate) => candidate.label === label);
        if (node && selectFromHook) selectFromHook(node);
      },
    };
    return () => {
      delete (window as unknown as Record<string, unknown>).__araigumaTopology;
    };
  });
</script>

<div class="topology-view">
  <header class="view-head">
    <div>
      <h1>Network topology</h1>
      <p class="sub">
        {document.nodes.length} nodes · {document.edges.length} evidenced relations ·
        a deterministic layered map — relationships without evidence are not drawn
      </p>
    </div>
    <DataBadge />
  </header>

  {#if document.nodes.length === 0}
    <div class="empty-state" data-testid="topology-empty">
      <p>No observed interfaces — the topology is legitimately empty.</p>
      <p class="sub">
        This is a valid observation of an empty environment, not an error.
      </p>
    </div>
  {:else}
    <div class="map-row">
      <section
        class="canvas-panel"
        data-testid="topology-canvas"
        aria-label="Layered fabric map of observed interfaces and evidenced relations"
      >
        <svg
          class="fabric"
          viewBox={`0 0 ${layout.width} ${layout.height}`}
          preserveAspectRatio="xMidYMid meet"
          role="group"
          aria-label="Topology fabric"
        >
          <defs>
            <marker
              id="arrow-observed"
              viewBox="0 0 10 10"
              refX="9"
              refY="5"
              markerWidth="7"
              markerHeight="7"
              orient="auto-start-reverse"
            >
              <path d="M 0 0 L 10 5 L 0 10 z" fill="#5b6576" />
            </marker>
            <marker
              id="arrow-inferred"
              viewBox="0 0 10 10"
              refX="9"
              refY="5"
              markerWidth="7"
              markerHeight="7"
              orient="auto-start-reverse"
            >
              <path d="M 0 0 L 10 5 L 0 10 z" fill="#3c5a74" />
            </marker>
          </defs>

          <g class="edges" aria-hidden="true">
            {#each layout.edges as laid (laid.index)}
              <path
                class="edge {laid.observed ? 'observed' : 'inferred'} {laid.structural
                  ? 'structural'
                  : 'gateway'} {highlightKeys.has(laid.from.key) ||
                highlightKeys.has(laid.to.key)
                  ? 'highlighted'
                  : ''}"
                d={laid.path}
                marker-end={laid.observed
                  ? 'url(#arrow-observed)'
                  : 'url(#arrow-inferred)'}
              >
                <title>
                  {laid.from.node.label} → {laid.to.node.label} · {edgeKindLabel(
                    laid.edge.edgeKind,
                  )} · {evidenceLabel(laid.edge.evidence)}
                </title>
              </path>
            {/each}
          </g>

          <g class="nodes">
            {#each layout.nodes as laid (laid.key)}
              <g
                class="node kind-{laid.node.nodeKind} state-{laid.node.state} {highlightKeys.has(
                  laid.key,
                )
                  ? 'highlighted'
                  : ''}"
                role="button"
                tabindex="0"
                aria-label={nodeAria(laid.node)}
                data-testid="topology-node-{laid.node.label}"
                onclick={() => select(laid.node)}
                onkeydown={(event) => onNodeKey(event, laid.node)}
              >
                <title>{nodeAria(laid.node)}</title>
                {#if laid.node.nodeKind === 'gateway'}
                  <polygon class="shape" points={hexPoints(laid)} />
                  <circle class="state-dot gateway-dot" cx={laid.x - 58} cy={laid.y - 14} r="3.5" />
                {:else}
                  <rect
                    class="shape"
                    x={laid.x - NODE_W / 2}
                    y={laid.y - NODE_H / 2}
                    width={NODE_W}
                    height={NODE_H}
                    rx="10"
                  />
                  <circle class="state-dot" cx={laid.x - 58} cy={laid.y - 14} r="3.5" />
                {/if}
                <text
                  class="node-label"
                  x={laid.x}
                  y={laid.y - 2}
                  text-anchor="middle"
                  font-size={labelFontSize(laid.node.label)}
                >
                  {laid.node.label}
                </text>
                <text class="node-kind" x={laid.x} y={laid.y + 16} text-anchor="middle">
                  {nodeSubtitle(laid.node)}
                </text>
              </g>
            {/each}
          </g>
        </svg>
      </section>

      <aside class="side">
        <section class="panel legend-panel" aria-label="Topology legend">
          <h2>Legend</h2>
          <div class="legend-grid">
            <span class="legend-item"><span class="swatch active"></span>interface up</span>
            <span class="legend-item"><span class="swatch inactive"></span>interface down</span>
            <span class="legend-item"><span class="swatch unknown"></span>state unknown</span>
            <span class="legend-item"><span class="swatch gateway"></span>gateway (routing fact)</span>
            <span class="legend-item"><span class="line"></span>observed relation</span>
            <span class="legend-item"><span class="line dashed"></span>inferred relation</span>
          </div>
          <p class="legend-note">
            Anything beyond a gateway — upstream or internet — is not observed and not drawn.
          </p>
        </section>

        <section class="panel service-panel" data-testid="topology-services" aria-label="Service observations">
          <h2>Service observations</h2>
          <p class="service-source">
            {#if snapshot}
              From the current snapshot · observed {formatObservationTime(snapshot.timestampMs)}
            {:else}
              No snapshot document is available
            {/if}
          </p>

          {#if snapshot && dns && connections}
            <button
              class="service-card"
              data-testid="topology-service-dns"
              onclick={() => navigateTo('dns')}
            >
              <span class="service-top">
                <span class="service-name">DNS configuration</span>
                <span class="evidence {dns.state}">{availabilityEvidenceLabel(dns.state)}</span>
              </span>
              <span class="service-value">
                {#if dns.state === 'observed'}
                  {formatCount(dnsObservations.length, 'scope')} · {formatCount(dnsServers, 'server')}
                {:else}
                  {dns.label}
                {/if}
              </span>
              <span class="service-detail">{dns.detail}</span>
            </button>

            <button
              class="service-card"
              data-testid="topology-service-connections"
              onclick={() => navigateTo('connections')}
            >
              <span class="service-top">
                <span class="service-name">Connections</span>
                <span class="evidence {connections.state}">
                  {availabilityEvidenceLabel(connections.state)}
                </span>
              </span>
              <span class="service-value">
                {#if connections.state === 'observed'}
                  {activeConnections} / {connectionObservations.length} active
                {:else}
                  {connections.label}
                {/if}
              </span>
              <span class="service-detail">{connections.detail}</span>
            </button>

            {#if differentObservationTimes}
              <p class="service-warning">
                The snapshot and topology documents have different observation
                times. Services are shown from the snapshot only; the topology
                is not extended with snapshot facts.
              </p>
            {/if}
          {:else}
            <p class="service-empty">
              The topology document does not carry DNS or connection
              observations. Import or select a snapshot to inspect those
              services; nothing is inferred from this document.
            </p>
          {/if}
        </section>
      </aside>
    </div>

    <section class="panel ledger" aria-label="Evidenced relations">
      <div class="ledger-head">
        <h2>Evidenced relations ({document.edges.length})</h2>
        <p>Every relation is listed exactly as projected; this view adds none.</p>
      </div>
      {#if edgeRows.length === 0}
        <p class="empty-note">No evidenced relations are present in this document.</p>
      {:else}
        <ol class="ledger-list">
          {#each edgeRows as row (row.key)}
            <li class="ledger-row {row.observed ? 'observed' : 'inferred'}">
              <span class="ledger-index mono">{row.index + 1}</span>
              <span class="ledger-path">
                <button class="node-link" onclick={() => select(row.from)}>
                  {row.from.label}
                </button>
                <span class="arrow" aria-hidden="true">→</span>
                <button class="node-link" onclick={() => select(row.to)}>
                  {row.to.label}
                </button>
              </span>
              <span class="ledger-kind">{row.kind}</span>
              <span class="ledger-evidence {row.observed ? 'observed' : 'inferred'}">
                {row.evidence}
              </span>
              {#if row.edge.detail}
                <span class="ledger-detail">{row.edge.detail}</span>
              {/if}
            </li>
          {/each}
        </ol>
      {/if}
    </section>
  {/if}
</div>

<style>
  .topology-view {
    padding: 22px 26px 32px;
    max-width: 1200px;
  }

  .view-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    margin-bottom: 16px;
  }

  h1 {
    margin: 0;
    font-size: 19px;
    font-weight: 600;
  }

  h2 {
    margin: 0 0 10px;
    font-size: 12px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--text-secondary);
  }

  .sub {
    margin: 4px 0 0;
    color: var(--text-secondary);
    font-size: 12.5px;
    max-width: 700px;
  }

  .map-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 14px;
    align-items: stretch;
  }

  @media (max-width: 960px) {
    .map-row {
      grid-template-columns: 1fr;
    }
  }

  .canvas-panel {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 520px;
    padding: 10px;
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-m);
    background:
      radial-gradient(
        circle at 50% 45%,
        color-mix(in srgb, var(--accent) 5%, transparent),
        transparent 62%
      ),
      var(--bg-inset);
    overflow: hidden;
  }

  @media (max-width: 960px) {
    .canvas-panel {
      height: 440px;
    }
  }

  .fabric {
    width: 100%;
    height: 100%;
    display: block;
  }

  .edge {
    fill: none;
    stroke-width: 1.8;
    stroke-linecap: round;
    transition: stroke 120ms ease, stroke-width 120ms ease;
  }

  .edge.observed {
    stroke: #5b6576;
  }

  .edge.inferred {
    stroke: #4f7ba6;
    stroke-dasharray: 6 5;
  }

  .edge.structural {
    stroke: #41507a;
  }

  .edge.highlighted {
    stroke: #e8eaef;
    stroke-width: 2.6;
  }

  .node {
    cursor: pointer;
  }

  .node:focus-visible {
    outline: none;
  }

  .node .shape {
    fill: var(--bg-raised);
    stroke: var(--border-strong);
    stroke-width: 1.5;
    transition: stroke 120ms ease, fill 120ms ease, stroke-width 120ms ease;
  }

  .node.state-active .shape {
    fill: color-mix(in srgb, var(--state-up) 9%, var(--bg-raised));
    stroke: var(--state-up);
  }

  .node.state-inactive .shape {
    fill: color-mix(in srgb, var(--state-down) 9%, var(--bg-raised));
    stroke: var(--state-down);
  }

  .node.state-unknown .shape {
    fill: color-mix(in srgb, var(--state-unknown) 8%, var(--bg-raised));
    stroke: var(--state-unknown);
  }

  .node.kind-gateway .shape {
    fill: color-mix(in srgb, var(--accent) 7%, var(--bg-raised));
    stroke: var(--accent);
  }

  .node.highlighted .shape,
  .node:focus-visible .shape {
    stroke: #e8eaef;
    stroke-width: 3;
  }

  .node:hover .shape {
    stroke-width: 2.4;
  }

  .node-label {
    fill: var(--text-primary);
    font-family: var(--font-mono);
    font-weight: 600;
    pointer-events: none;
  }

  .node-kind {
    fill: var(--text-muted);
    font-size: 9.5px;
    letter-spacing: 0.04em;
    pointer-events: none;
  }

  .state-dot {
    pointer-events: none;
  }

  .state-active .state-dot {
    fill: var(--state-up);
  }

  .state-inactive .state-dot {
    fill: var(--state-down);
  }

  .state-unknown .state-dot {
    fill: var(--state-unknown);
  }

  .gateway-dot {
    fill: var(--accent);
  }

  .side {
    display: flex;
    flex-direction: column;
    gap: 14px;
    min-width: 0;
  }

  @media (max-width: 960px) {
    .side {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
    }
  }

  @media (max-width: 640px) {
    .side {
      grid-template-columns: 1fr;
    }
  }

  .panel {
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-m);
    background: var(--bg-raised);
    padding: 14px 16px;
  }

  .legend-grid {
    display: flex;
    flex-direction: column;
    gap: 7px;
    font-size: 11.5px;
    color: var(--text-secondary);
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 9px;
  }

  .swatch {
    width: 12px;
    height: 12px;
    border-radius: 50%;
